/** FIFO-capped delivery-id dedupe. One instance per channel mount, not process-global. */
const DEFAULT_CAP = 2_000;
export function createEventIdDedupe(cap = DEFAULT_CAP) {
    return createReleasableEventIdDedupe(cap);
}
export function createReleasableEventIdDedupe(cap = DEFAULT_CAP) {
    const handled = new Set();
    return {
        tryHandle(eventId) {
            if (handled.has(eventId)) {
                return false;
            }
            handled.add(eventId);
            if (handled.size > cap) {
                const first = handled.values().next().value;
                if (first !== undefined) {
                    handled.delete(first);
                }
            }
            return true;
        },
        release(eventId) {
            handled.delete(eventId);
        },
    };
}
